import{_ as s,C as d,o as n,c,j as o,a as r,E as t,a2 as i}from"./chunks/framework.BxGh02fV.js";const _=JSON.parse('{"title":"Documentation","description":"","frontmatter":{"title":"Documentation"},"headers":[],"relativePath":"agent/documentation.md","filePath":"agent/documentation.md"}'),l={name:"agent/documentation.md"};function u(f,a,m,p,h,v){const e=d("Ask");return n(),c("div",null,[a[0]||(a[0]=o("h1",{id:"documentation",tabindex:"-1"},[r("Documentation "),o("a",{class:"header-anchor",href:"#documentation","aria-label":'Permalink to "Documentation"'},"​")],-1)),a[1]||(a[1]=o("p",null,"Ce parcours couvre trois choses : lire la documentation de cadrage de votre projet, tenir sa documentation utilisateur (celle que lisent vos utilisateurs), et traduire l'interface et les descriptions des outils. Vous y venez pour retrouver un document, vérifier que la documentation suit le produit, ou ajouter une langue.",-1)),a[2]||(a[2]=o("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[r("Ce que vous demandez à l'agent "),o("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),t(e,{say:"Quels documents de cadrage a ce projet ?",verb:"effortless_docs_list",family:"documentation"}),t(e,{say:"Cherche dans la documentation tout ce qui parle de la livraison.",verb:"effortless_docs_search",family:"documentation",args:'{"query":"livraison"}'}),t(e,{say:"Lis-moi le document blueprints/012-Epic-Export/cadrage.md en entier.",verb:"effortless_doc_read",family:"documentation",args:'{"rel_path":"blueprints/012-Epic-Export/cadrage.md"}'}),t(e,{say:"Notre documentation utilisateur couvre-t-elle tout ? Y a-t-il des pages vieillies ?",verb:"effortless_user_doc_coverage",family:"documentation"}),t(e,{say:"Vérifie l'inventaire de la documentation utilisateur.",verb:"effortless_user_doc_inventory",family:"documentation"}),t(e,{say:"Le build de la documentation est fait dans dist/docs : écris son manifeste.",verb:"effortless_user_doc_manifest",family:"documentation",args:'{"output_dir":"dist/docs"}'}),t(e,{say:"Installe la nouvelle copie hors ligne de la documentation : la candidate est dans dist/docs, la préproduction dans dist/staging, la copie courante dans app/docs.",verb:"effortless_user_doc_sync",family:"documentation",args:'{"source_dir":"dist/docs","staging_dir":"dist/staging","current_dir":"app/docs"}'}),t(e,{say:"Quelles clés de l'interface ne sont pas encore traduites en espagnol ? Traduis-les.",verb:"effortless_i18n_status",family:"documentation",args:'{"surface":"front","lang":"es"}'}),t(e,{say:"Montre-moi le catalogue anglais des descriptions d'outils.",verb:"effortless_i18n_export",family:"documentation",args:'{"surface":"mcp","lang":"en"}'}),a[3]||(a[3]=i('<h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><h3 id="lire-et-chercher-la-documentation-de-cadrage" tabindex="-1">Lire et chercher la documentation de cadrage <a class="header-anchor" href="#lire-et-chercher-la-documentation-de-cadrage" aria-label="Permalink to &quot;Lire et chercher la documentation de cadrage&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/documentation.html#project-docs-list"><code>effortless_project_docs_list</code></a> liste les documents de cadrage du projet : les fichiers à la racine de <code>blueprints/</code> dont l&#39;en-tête porte <code>type: cadrage-projet</code>.</li><li><a href="/Effortless/reference/mcp/documentation.html#docs-list"><code>effortless_docs_list</code></a> liste tous les documents Markdown de <code>blueprints/</code>, sous-dossiers compris, avec leur titre.</li><li><a href="/Effortless/reference/mcp/documentation.html#docs-search"><code>effortless_docs_search</code></a> avec <code>query</code> cherche dans ces documents, sans tenir compte de la casse ni des accents. Les résultats sont classés par nombre d&#39;occurrences, chacun avec un extrait.</li><li><a href="/Effortless/reference/mcp/documentation.html#doc-read"><code>effortless_doc_read</code></a> avec <code>rel_path</code> (relatif à la racine du projet) lit un document. Il refuse tout chemin hors de <code>blueprints/</code>.</li></ol><p>Ces quatre verbes ne font que lire.</p><h3 id="tenir-la-documentation-utilisateur" tabindex="-1">Tenir la documentation utilisateur <a class="header-anchor" href="#tenir-la-documentation-utilisateur" aria-label="Permalink to &quot;Tenir la documentation utilisateur&quot;">​</a></h3><p>La documentation utilisateur est déclarée dans un fichier <code>userdoc.json</code> à la racine d&#39;une stack. Les quatre verbes prennent <code>stack_id</code> ; sans lui, l&#39;agent vise la seule stack qui déclare une documentation utilisateur.</p><ol><li><a href="/Effortless/reference/mcp/documentation.html#user-doc-inventory"><code>effortless_user_doc_inventory</code></a> lit et valide l&#39;inventaire déclaré, et résout chaque source une fois.</li><li><a href="/Effortless/reference/mcp/documentation.html#user-doc-coverage"><code>effortless_user_doc_coverage</code></a> fait le diagnostic : trous (une source que personne ne documente), pages vieillies (la source a bougé depuis la génération), pages orphelines (la source a disparu). <code>regime</code> vaut <code>observation</code> (par défaut : les constats sont rendus sans bloquer) ou <code>publication</code> (les constats bloquent).</li><li><a href="/Effortless/reference/mcp/documentation.html#user-doc-manifest"><code>effortless_user_doc_manifest</code></a> avec <code>output_dir</code> (relatif à la stack, sans défaut) clôt un build déjà produit : il interroge la paire de versions par la commande déclarée et écrit le manifeste en dernier. S&#39;il ne peut pas le produire, il retire toute la sortie.</li><li><a href="/Effortless/reference/mcp/documentation.html#user-doc-sync"><code>effortless_user_doc_sync</code></a> avec <code>source_dir</code>, <code>staging_dir</code> et <code>current_dir</code> installe une copie hors ligne : la candidate est écrite en préproduction, son manifeste est relu, et la version de format est demandée à la coque. Une copie d&#39;un autre format est refusée et la copie en place est conservée.</li></ol><h3 id="traduire-l-interface-et-les-descriptions-des-outils" tabindex="-1">Traduire l&#39;interface et les descriptions des outils <a class="header-anchor" href="#traduire-l-interface-et-les-descriptions-des-outils" aria-label="Permalink to &quot;Traduire l&#39;interface et les descriptions des outils&quot;">​</a></h3><p>Deux surfaces se traduisent : <code>front</code> (l&#39;interface) et <code>mcp</code> (les descriptions des outils). Le français est la source ; il ne s&#39;écrit jamais.</p><ol><li><a href="/Effortless/reference/mcp/documentation.html#i18n_status"><code>effortless_i18n_status</code></a> avec <code>surface</code> et <code>lang</code> rend le delta : les clés absentes (avec leur texte français) et les clés traduites par machine qu&#39;aucun humain n&#39;a relues.</li><li>L&#39;agent traduit lui-même ce delta, puis appelle <a href="/Effortless/reference/mcp/documentation.html#i18n_apply"><code>effortless_i18n_apply</code></a> avec <code>entries</code> (des clés plates vers le texte). Les traductions vont dans <code>~/.effortless/locales/&lt;surface&gt;/&lt;lang&gt;.json</code> et sont marquées « machine ». Avec <code>reviewed: true</code>, elles sont marquées relues par un humain, et ne sont plus écrasées par une traduction machine.</li><li><a href="/Effortless/reference/mcp/documentation.html#i18n_export"><code>effortless_i18n_export</code></a> rend le catalogue complet (livré et vos ajouts) d&#39;une surface et d&#39;une langue, pour inspection ou sauvegarde.</li></ol><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><ul><li>Des documents retrouvés et lus sans que vous ouvriez le dossier <code>blueprints/</code>. Ils se lisent aussi dans l&#39;écran <a href="/Effortless/guide/knowledge.html">Connaissance</a> (lentilles de cadrage et champ de recherche).</li><li>Un diagnostic de couverture avec un code de sortie : conforme, trou, vieillie, orpheline, ou l&#39;un des refus (inventaire invalide, mesure impossible, page altérée).</li><li>Un manifeste de build et une copie hors ligne installée, quand vous les demandez.</li><li>Des fichiers de traduction dans votre dossier personnel, sans toucher au code livré.</li></ul><h2 id="quand-l-agent-est-refuse" tabindex="-1">Quand l&#39;agent est refusé <a class="header-anchor" href="#quand-l-agent-est-refuse" aria-label="Permalink to &quot;Quand l&#39;agent est refusé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Ce que dit le refus</th><th>Ce qu&#39;il faut faire</th></tr></thead><tbody><tr><td>Chemin hors de <code>blueprints/</code>, absolu ou remontant</td><td>« Chemin hors périmètre. »</td><td>Donner un chemin relatif sous <code>blueprints/</code>, tel que rendu par <code>effortless_docs_list</code>.</td></tr><tr><td>Aucune stack ne déclare de documentation utilisateur</td><td><code>userDoc:usage</code> (« aucune stack ne porte de userdoc.json »)</td><td>Déclarer la documentation utilisateur d&#39;une stack.</td></tr><tr><td>Plusieurs stacks la déclarent</td><td><code>userDoc:usage</code> (les stacks sont nommées)</td><td>Passer <code>stack_id</code>.</td></tr><tr><td><code>stack_id</code> inconnu</td><td><code>userDoc:usage</code></td><td>Lister les stacks avec <code>effortless_stack_list</code> (voir <a href="/Effortless/agent/code.html">Code et stacks</a>).</td></tr><tr><td>Inventaire invalide (code 5)</td><td><code>userDoc:inventoryInvalid</code></td><td>Corriger l&#39;inventaire, <code>effortless_user_doc_coverage</code> nomme ce qui manque.</td></tr><tr><td>Mesure impossible (code 6)</td><td><code>userDoc:unmeasurable</code></td><td>Une commande déclarée a échoué : la lire dans le message et la corriger.</td></tr><tr><td>Page altérée (code 7)</td><td><code>userDoc:pageAltered</code></td><td>Régénérer la page dérivée plutôt que la modifier à la main.</td></tr><tr><td>Couverture bloquante en régime <code>publication</code></td><td><code>userDoc:coverageBlocking</code></td><td>Combler la couverture décrite dans le rapport, ou repasser en <code>observation</code>.</td></tr><tr><td>Copie à installer d&#39;un autre format que celui de la coque</td><td>un refus <code>userDoc:*</code> ; la copie en place est conservée</td><td>Reconstruire la documentation avec la bonne version de format.</td></tr><tr><td>Surface de traduction invalide</td><td>« surface invalide … (attendu : front, mcp) »</td><td>Passer <code>front</code> ou <code>mcp</code>.</td></tr><tr><td>Écriture en français</td><td>« Le français est la source : écriture interdite. »</td><td>Traduire vers une autre langue (<code>en</code>, <code>es</code>, <code>ru</code>…).</td></tr></tbody></table>',14))])}const b=s(l,[["render",u]]);export{_ as __pageData,b as default};
